/**
 * Rhino 脚本注入常量定义
 * 对应 Android 端的注入对象
 */

/**
 * WebView JS 注入对象
 * 来自: com.fanfanlo.lib.components.webview.WebViewJsInjectKeys
 */
export enum WebViewJsInjectKeys {
    /** 全局Window，可以派发window的退出事件 */
    Window = "Window",
    /** 可以调用强制关闭window */
    WindowUtils = "WindowUtils",
    /** js调用执行java脚本的webviewjs的对象 */
    webViewJs = "webViewJs",
    /** 控制台对象 */
    console = "console",
    /** UI线程工具 */
    UIThreadUtil = "UIThreadUtil",
}

/**
 * Rhino 脚本注入对象
 * 来自: com.fanfanlo.droidlib.auto.rhino.InjectNames
 */
export enum RhinoInjectNames {
    /** EventDispatcher供脚本内部使用 */
    dispatcher = "dispatcher",
    /** 提供方便使用的方法（目前未使用） */
    quicker = "quicker",
    /** 当前指向的是RhinoRunner */
    javaRunner = "javaRunner",
    /** 自动化代理DroidProxy */
    proxy = "proxy",
    /** @deprecated 辅助功能套壳（已废弃，限制比方便更大） */
    a11yProxy = "a11yProxy",
    /** 辅助功能 */
    a11yModel = "a11yModel",
    /** WebView JS 分发器 */
    WebViewJsDispatcher = "WebViewJsDispatcher",
}

/**
 * 所有可用的注入对象键名
 */
export const AllInjectKeys = {
    ...WebViewJsInjectKeys,
    ...RhinoInjectNames,
} as const

/**
 * 注入对象键名的联合类型
 */
export type InjectKeyType = WebViewJsInjectKeys | RhinoInjectNames

/**
 * 获取所有注入键名的数组
 */
export function getAllInjectKeys(): string[] {
    return [
        ...Object.values(WebViewJsInjectKeys),
        ...Object.values(RhinoInjectNames),
    ]
}

/**
 * 检查是否是有效的注入键名
 */
export function isValidInjectKey(key: string): boolean {
    return getAllInjectKeys().includes(key)
}
