import _ from "lodash"
import { ulid } from "ulid"
import { createDefaultTriggerActionGroup, ITriggerActionGroup, mergeTriggerActionGroupToDefaultData } from "../trigger-action/ITriggerActionGroup"
export interface IProjectJavaData {
}

export interface IProjectShellData{
    id:string
}
export interface IProjectData{
    id:string
    type:string
    originId?:string
    name?:string
    localName?:string
    triggerActionGroup:ITriggerActionGroup
    keepAlive?:boolean
}

export function createProjectDefaultData():IProjectData{
    return {
        type:'project',
        id:ulid(),
        triggerActionGroup:createDefaultTriggerActionGroup()
    }

}

export function mergeProjectDataToDefaultData(data:Partial<IProjectData>):IProjectData{
    const result = _.merge(createProjectDefaultData(), data);
    result.triggerActionGroup = mergeTriggerActionGroupToDefaultData(result.triggerActionGroup)
    return result   
}
