import { Dispatcher } from "@fanfanlo";
import { projectModel } from "./ProjectModel";
import _ from "lodash";
export class ProjectController extends Dispatcher{

    constructor(){
        super();
    }
    async init (){
        console.log('[ProjectController.init] 开始初始化ProjectController')
        await projectModel.init();
        console.log('[ProjectController.init] ProjectController初始化完成')
    }

}

export const projectController = new ProjectController();
