import { triggerTimeoutUtils } from "./time/timeout/ITriggerTimeout.inft";
import { triggerWhenActivityInUtils } from "./app/when-activity-in/ITriggerWhenActivityIn";
import { triggerNodeTriggerUtils } from "./a11y/node-trigger/ITriggerNodeTrigger";
import { Log } from "@fanfanlo";
const fileLog = new Log(false, 'initTriggers_f')
fileLog.pause = false;
fileLog.childrenPaused = false;
export function initTriggers(){
    fileLog.log('[initTriggers] initializing all trigger types');

    triggerTimeoutUtils.init()
    fileLog.log('[initTriggers] triggerTimeoutUtils initialized');

    triggerWhenActivityInUtils.init()
    fileLog.log('[initTriggers] triggerWhenActivityInUtils initialized');

    triggerNodeTriggerUtils.init()
    fileLog.log('[initTriggers] triggerNodeTriggerUtils initialized');

}
